+    btn.addEventListener("keydown", (e) => {
+      const idx = buttons.indexOf(btn);
+      if (e.key === "ArrowRight") {
+        e.preventDefault();
+        const next = buttons[(idx + 1) % buttons.length];
+        next.focus();
+        setActive(next);
+      }
+      if (e.key === "ArrowLeft") {
+        e.preventDefault();
+        const prev = buttons[(idx - 1 + buttons.length) % buttons.length];
+        prev.focus();
+        setActive(prev);
